import 'dart:typed_data';

import 'package:excel_community/excel_community.dart';
import 'package:flutter/foundation.dart';
import 'package:uuid/uuid.dart';

/// Matches the JSON structure generated by apps/web/src/lib/xlsx.js.
/// The resulting snapshot is saved through /drive/sheets/:id and is readable
/// by the existing web Univer editor (not stored as a raw attachment).
class ExcelToUniver {
  ExcelToUniver._();

  static const supportedExtensions = {'xlsx', 'xlsm', 'xls'};

  static bool supportsFilename(String filename) {
    final lastDot = filename.lastIndexOf('.');
    if (lastDot < 0) return false;
    return supportedExtensions.contains(
      filename.substring(lastDot + 1).toLowerCase(),
    );
  }

  static String spreadsheetName(String filename) {
    if (!supportsFilename(filename)) {
      throw const FormatException('Choose an Excel file (.xlsx, .xlsm or .xls)');
    }
    final dot = filename.lastIndexOf('.');
    final name = filename.substring(0, dot).trim();
    if (name.isEmpty || name.length > 200 ||
        name == '.' || name == '..' ||
        RegExp(r'[\x00-\x1f/\\]').hasMatch(name)) {
      throw const FormatException('Invalid Excel filename (maximum 200 characters)');
    }
    return name;
  }

  /// Parse off the UI isolate so larger workbooks do not freeze navigation.
  static Future<Map<String, dynamic>> convert(
    Uint8List bytes, {
    required String name,
  }) {
    if (bytes.isEmpty) {
      throw const FormatException('The selected Excel file is empty');
    }
    return compute(_buildSnapshot, <String, dynamic>{
      'bytes': bytes,
      'name': name,
    });
  }
}

Map<String, dynamic> _buildSnapshot(Map<String, dynamic> request) {
  final bytes = request['bytes'] as Uint8List;
  final name = request['name'] as String;
  late final Excel workbook;
  try {
    workbook = Excel.decodeBytes(bytes.toList(growable: false));
  } catch (_) {
    throw const FormatException('This Excel file is damaged or unsupported');
  }

  final order = <String>[];
  final sheets = <String, dynamic>{};
  final used = <String>{};
  const uuid = Uuid();

  for (final originalName in workbook.tables.keys) {
    final sheet = workbook.tables[originalName];
    if (sheet == null) continue;

    final id = uuid.v4();
    final cleanName = _uniqueSheetName(originalName, used);
    final cellData = <String, dynamic>{};
    var maxRow = 0;
    var maxColumn = 0;

    // Use the source positions, not a dense JSON matrix; Univer expects
    // cellData[rowIndex][columnIndex] for each non-empty/styled cell.
    for (final row in sheet.rows) {
      for (final cell in row) {
        if (cell == null) continue;
        final serialized = _serializeCell(cell);
        if (serialized.isEmpty) continue;
        final r = cell.rowIndex;
        final c = cell.columnIndex;
        if (r < 0 || c < 0) continue;
        maxRow = r > maxRow ? r : maxRow;
        maxColumn = c > maxColumn ? c : maxColumn;
        final rowMap = cellData.putIfAbsent(
          r.toString(),
          () => <String, dynamic>{},
        ) as Map<String, dynamic>;
        rowMap[c.toString()] = serialized;
      }
    }

    // Preserve multiple worksheets and merged ranges, as the web importer does.
    final merges = <Map<String, int>>[];
    for (final range in workbook.getMergedCells(originalName)) {
      final bounds = _mergeBounds(range);
      if (bounds == null) continue;
      merges.add(bounds);
      maxRow = bounds['endRow']! > maxRow ? bounds['endRow']! : maxRow;
      maxColumn =
          bounds['endColumn']! > maxColumn ? bounds['endColumn']! : maxColumn;
    }

    final rowData = <String, dynamic>{};
    for (final height in sheet.getRowHeights.entries) {
      if (height.value.isFinite && height.value > 0) {
        rowData[height.key.toString()] = {'h': height.value.round()};
      }
    }
    for (final row in sheet.getHiddenRows) {
      final key = row.toString();
      final metadata = (rowData[key] as Map<String, dynamic>?) ??
          <String, dynamic>{};
      metadata['hd'] = 1;
      rowData[key] = metadata;
    }

    final columnData = <String, dynamic>{};
    for (final width in sheet.getColumnWidths.entries) {
      if (width.value.isFinite && width.value > 0) {
        // Excel's widths are in character units; Univer uses pixels.
        columnData[width.key.toString()] = {'w': (width.value * 8).round()};
      }
    }
    for (final column in sheet.getHiddenColumns) {
      final key = column.toString();
      final metadata = (columnData[key] as Map<String, dynamic>?) ??
          <String, dynamic>{};
      metadata['hd'] = 1;
      columnData[key] = metadata;
    }

    order.add(id);
    sheets[id] = <String, dynamic>{
      'id': id,
      'name': cleanName,
      'tabColor': '',
      'hidden': 0,
      'rowCount': sheet.maxRows > maxRow + 1
          ? (sheet.maxRows > 1000 ? sheet.maxRows : 1000)
          : (maxRow + 1 > 1000 ? maxRow + 1 : 1000),
      'columnCount': sheet.maxColumns > maxColumn + 1
          ? (sheet.maxColumns > 20 ? sheet.maxColumns : 20)
          : (maxColumn + 1 > 20 ? maxColumn + 1 : 20),
      'zoomRatio': 1,
      'freeze': {
        'startRow': -1,
        'startColumn': -1,
        'ySplit': 0,
        'xSplit': 0,
      },
      'scrollTop': 0,
      'scrollLeft': 0,
      'defaultColumnWidth': 73,
      'defaultRowHeight': 23,
      'mergeData': merges,
      'cellData': cellData,
      'rowData': rowData,
      'columnData': columnData,
      'showGridlines': 1,
      'rowHeader': {'width': 46, 'hidden': 0},
      'columnHeader': {'height': 20, 'hidden': 0},
      'rightToLeft': sheet.isRTL ? 1 : 0,
    };
  }

  if (order.isEmpty) {
    throw const FormatException('This workbook does not contain any worksheets');
  }

  return <String, dynamic>{
    'id': uuid.v4(),
    'name': name,
    'appVersion': '1.0.2',
    'locale': 'enUS',
    'styles': <String, dynamic>{},
    'sheetOrder': order,
    'sheets': sheets,
  };
}

String _uniqueSheetName(String source, Set<String> used) {
  final sanitized = source
      .replaceAll(RegExp(r'[\\/?*\[\]:]'), ' ')
      .trim();
  final base = sanitized.isEmpty
      ? 'Sheet'
      : (sanitized.length > 31 ? sanitized.substring(0, 31) : sanitized);
  var candidate = base;
  var number = 2;
  while (!used.add(candidate.toLowerCase())) {
    final suffix = ' $number';
    candidate = base.substring(0, base.length < 31 - suffix.length
            ? base.length
            : 31 - suffix.length) +
        suffix;
    number++;
  }
  return candidate;
}

Map<String, int>? _mergeBounds(String range) {
  final parts = range.replaceAll(r'$', '').split(':');
  if (parts.length != 2) return null;
  final start = _a1(parts[0]);
  final end = _a1(parts[1]);
  if (start == null || end == null) return null;
  return <String, int>{
    'startRow': start.$1,
    'startColumn': start.$2,
    'endRow': end.$1,
    'endColumn': end.$2,
  };
}

(int, int)? _a1(String address) {
  final match = RegExp(r'^([A-Za-z]+)([1-9]\d*)$').firstMatch(address);
  if (match == null) return null;
  final row = int.parse(match.group(2)!) - 1;
  var column = 0;
  for (final char in match.group(1)!.toUpperCase().codeUnits) {
    column = column * 26 + char - 64;
  }
  return (row, column - 1);
}

Map<String, dynamic> _serializeCell(Data cell) {
  final value = cell.value;
  final result = <String, dynamic>{};

  if (value is FormulaCellValue) {
    final formula = value.formula;
    if (formula.isNotEmpty) {
      result['f'] = formula.startsWith('=') ? formula : '=$formula';
    }
    final cached = _plainValue(value.cachedValue, cell);
    if (cached != null) result['v'] = cached;
  } else {
    final raw = _plainValue(value, cell);
    if (raw != null) result['v'] = raw;
  }

  final format = cell.cellStyle?.numberFormat.formatCode;
  if (format != null && format.isNotEmpty && format != 'General') {
    result['s'] = <String, dynamic>{
      'n': <String, String>{'pattern': format},
    };
  }
  return result;
}

Object? _plainValue(CellValue? value, Data cell) {
  return switch (value) {
    null => null,
    IntCellValue v => v.value,
    DoubleCellValue v => v.value.isFinite ? v.value : null,
    BoolCellValue v => v.value,
    TextCellValue _ => cell.displayText,
    DateCellValue v => _excelDateSerial(v.asDateTimeUtc()),
    DateTimeCellValue v => _excelDateSerial(v.asDateTimeUtc()),
    TimeCellValue v =>
      (v.hour * 3600 + v.minute * 60 + v.second +
              v.millisecond / 1000 + v.microsecond / 1000000) /
          86400,
    FormulaCellValue _ => null,
  };
}

double _excelDateSerial(DateTime date) {
  // Excel/SheetJS uses the 1900 epoch (with Excel's historical leap-year bug).
  final epoch = DateTime.utc(1899, 12, 30);
  return date.difference(epoch).inMilliseconds / 86400000.0;
}
